// Family feedback intake — captures Suggest-button submissions from the
// PWA. Pairs with workflow 31 (daily standup digest) which reads from
// /data/finance-events/family-feedback/ on the 7am cron.
//
// Per BUSINESS-PROCESS-CONNECTIONS Family-Voice-Is-The-Connection
// extension (2026-05-29): every family voice is a first-class internal
// connection that must be wired within 24 hours.
//
// POST body shape:
//   { sender, type, message, screen_context?, user_agent?, source? }
// - sender: 'dpoe' | 'cpoe' | 'christiana' | 'christian' | 'christyn' |
//   'unknown' (from PWA's current profile localStorage). Family members:
//   dpoe=Darrell, cpoe=Christina (wife), christiana=older daughter (UIUC),
//   christian=Darrell Christian Poe (twin son, 10), christyn=Christyn Elaine
//   Poe (twin daughter, 10). Twin voices get parental visibility (Darrell +
//   Christina see everything they submit).
// - type: 'bug' | 'feature' | 'copy' | 'question' | 'strategic' | 'other'
// - message: free-form text from the Suggest modal
// - screen_context: { path, tab, persona } - auto-captured by the PWA
// - user_agent: browser useragent for bug repro context
// - source: 'poetech.us' typically

const fs = require('fs');
const path = require('path');

const FEEDBACK_DIR = '/data/finance-events/family-feedback';
const NTFY_BASE = 'http://ntfy:80';
const NTFY_TOPIC = 'poetech-family-feedback';

try { fs.mkdirSync(FEEDBACK_DIR, { recursive: true }); } catch (_) {}

const input = $input.first().json || {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;

const sender = (body.sender || 'unknown').toString().trim().toLowerCase();
const type = (body.type || 'other').toString().trim().toLowerCase();
const message = (body.message || '').toString().trim();
const screen_context = (body.screen_context && typeof body.screen_context === 'object') ? body.screen_context : {};
const user_agent = (body.user_agent || '').toString().slice(0, 500);
const source = (body.source || 'poetech.us').toString().trim();
const screenshot = (body.screenshot || '').toString();

if (!message) {
  return [{ json: { ok: false, error: 'message is required' } }];
}

// Sender trust tier per AI-TEAM-DISTRIBUTION + family-first principle.
// Family voices get immediate-priority routing; unknown senders get
// captured but queued lower.
const trustedSenders = ['dpoe', 'cpoe', 'christiana', 'christian', 'christyn'];
const isFamily = trustedSenders.includes(sender);
const priority = isFamily ? 'family' : 'external';

const capturedAt = new Date().toISOString();
const id = 'fb-' + capturedAt.replace(/[:.]/g, '-') + '-' + Math.floor(Math.random() * 10000);
// 2026-06-13 - optional screenshot. The PWA sends a compressed JPEG data URL
// ('data:image/...;base64,...'); decode it to a sidecar file next to the JSON
// record so the Governor can open it. Best-effort: a bad/oversized image never
// blocks the text feedback.
let screenshot_file = null;
if (screenshot && screenshot.indexOf('data:image/') === 0 && screenshot.indexOf(';base64,') > 0) {
  try {
    const comma = screenshot.indexOf(',');
    const header = screenshot.slice(0, comma);
    const b64 = screenshot.slice(comma + 1);
    let ext = header.slice(header.indexOf('/') + 1, header.indexOf(';')).toLowerCase();
    if (ext === 'jpeg') ext = 'jpg';
    ext = ext.replace(/[^a-z0-9]/g, '') || 'jpg';
    const buf = Buffer.from(b64, 'base64');
    // Cap decoded size at ~3 MB so a runaway payload cannot fill the disk.
    if (buf.length > 0 && buf.length <= 3 * 1024 * 1024) {
      const imgFn = id + '.' + ext;
      fs.writeFileSync(path.join(FEEDBACK_DIR, imgFn), buf);
      screenshot_file = imgFn;
    }
  } catch (_) { /* bad image - keep the text feedback anyway */ }
}
const record = {
  id,
  screenshot_file,
  captured_at: capturedAt,
  sender,
  priority,
  type,
  message,
  screen_context,
  user_agent,
  source,
  status: 'new',
  governor_action: null,
  governor_action_at: null,
  ship_pr: null,
  ship_committed_at: null
};

const safeFn = id + '.json';
try { fs.writeFileSync(path.join(FEEDBACK_DIR, safeFn), JSON.stringify(record, null, 2)); }
catch (e) { return [{ json: { ok: false, error: 'write failed: ' + String(e) } }]; }

// Best-effort ntfy push so the Governor sees feedback as it arrives,
// not just at the 7am digest. Family voices get priority 4 (high);
// external gets priority 3 (default).
const senderLabel = sender === 'unknown' ? '(unknown sender)' : sender;
const typeLabel = type.charAt(0).toUpperCase() + type.slice(1);
const contextLabel = screen_context.path ? ' on ' + screen_context.path : '';
const preview = senderLabel + ' [' + typeLabel + ']' + contextLabel + ': ' + message.slice(0, 200) + (screenshot_file ? ' [+screenshot]' : '');
try {
  await fetch(NTFY_BASE + '/' + NTFY_TOPIC, {
    method: 'POST',
    headers: {
      'Title': 'PoeTech family feedback - ' + senderLabel,
      'Priority': isFamily ? '4' : '3',
      'Tags': 'speech_balloon',
      'Content-Type': 'text/plain'
    },
    body: preview,
    signal: AbortSignal.timeout(5000)
  });
} catch (_) { /* ntfy down or unavailable - captured locally either way */ }

return [{ json: { ok: true, id, captured_at: capturedAt, message: 'Thanks - your feedback is in. We review every voice and act on what we can.' } }];
